"use client";

import React, { useState } from "react";
import * as LucideIcons from "lucide-react";
import { Input } from "../../../components/ui/Input";
import { useBarber, AppointmentStatus } from "@/context/BarberContext";

// Safe icon renderer
function Icon({ name, className }: { name: string, className?: string }) {
    const LucideIcon = (LucideIcons as any)[name];
    if (!LucideIcon) return <div className={className} style={{ width: '20px', height: '20px', backgroundColor: '#333', borderRadius: '4px' }} />;
    return <LucideIcon className={className} />;
}

export default function AdminAgendamentos() {
    const { appointments, updateAppointmentStatus } = useBarber();
    const [searchTerm, setSearchTerm] = useState("");
    const [statusFilter, setStatusFilter] = useState("TODOS");

    const filteredAppointments = appointments.filter(apt => {
        const matchesSearch = apt.clientName.toLowerCase().includes(searchTerm.toLowerCase()) ||
            apt.barberName.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesStatus = statusFilter === "TODOS" || apt.status.toUpperCase() === statusFilter;
        return matchesSearch && matchesStatus;
    });

    const statusOptions = ["TODOS", "AGENDADO", "CONFIRMADO", "CONCLUIDO", "CANCELADO"];

    return (
        <div className="min-h-screen bg-[#0a0a0a] text-white p-6 lg:p-12 font-sans selection:bg-[#D4AF37] selection:text-black animate-fade-in-up">
            <div className="max-w-4xl mx-auto bg-[#111111] border border-[#1f1f1f] rounded-3xl p-8 shadow-2xl h-[calc(100vh-100px)] flex flex-col relative overflow-hidden">
                <header className="flex justify-between items-center mb-8">
                    <div className="flex items-center gap-3">
                        <Icon name="Calendar" className="w-6 h-6 text-[#D4AF37]" />
                        <h2 className="text-2xl font-bold tracking-tight">Agendamentos</h2>
                    </div>
                    <div className="flex bg-[#1a1a1a] p-1 rounded-xl border border-[#222] overflow-x-auto no-scrollbar">
                        {statusOptions.map(status => (
                            <button
                                key={status}
                                onClick={() => setStatusFilter(status)}
                                className={`px-4 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${statusFilter === status ? 'bg-[#D4AF37] text-black shadow-lg' : 'text-gray-500 hover:text-white'}`}
                            >
                                {status}
                            </button>
                        ))}
                    </div>
                </header>

                <div className="relative mb-8">
                    <Icon name="Search" className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
                    <Input
                        placeholder="Buscar por cliente ou barbeiro..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="pl-12 bg-[#1a1a1a] border-[#222] h-14 text-sm focus:border-[#D4AF37]/50"
                    />
                </div>

                <div className="flex-1 overflow-y-auto pr-2 space-y-4 custom-scrollbar">
                    {filteredAppointments.length > 0 ? filteredAppointments.map((apt) => (
                        <div key={apt.id} className="bg-[#1a1a1a]/50 border border-[#222] p-6 rounded-2xl flex items-center justify-between group hover:border-[#D4AF37]/20 transition-all">
                            <div className="flex items-center gap-6">
                                <div className="w-14 h-14 rounded-2xl bg-[#D4AF37]/10 flex items-center justify-center text-[#D4AF37] font-bold text-xl border border-[#D4AF37]/10 group-hover:bg-[#D4AF37] group-hover:text-black transition-all">
                                    {apt.clientName[0]}
                                </div>
                                <div>
                                    <h4 className="font-bold text-lg text-gray-100 mb-1">{apt.clientName}</h4>
                                    <p className="text-[10px] text-gray-500 uppercase tracking-widest font-black">
                                        {apt.serviceName} • <span className="text-[#D4AF37]">{apt.barberName}</span>
                                    </p>
                                </div>
                            </div>

                            <div className="flex items-center gap-12">
                                <div className="text-right">
                                    <div className="flex items-center gap-2 text-gray-400 text-[10px] uppercase font-black justify-end mb-1">
                                        <Icon name="Clock" className="w-3 h-3 text-[#D4AF37]" /> {apt.time}
                                    </div>
                                    <p className="text-white font-bold text-base tracking-tighter">R$ {apt.price.toFixed(2)}</p>
                                </div>

                                <div className="flex items-center gap-4">
                                    <span className={`text-[9px] font-black px-4 py-1.5 rounded-full border ${apt.status === 'agendado' ? 'bg-[#221c0b] text-[#D4AF37] border-[#D4AF37]/20' :
                                            apt.status === 'concluido' ? 'bg-[#0f2419] text-[#4ade80] border-[#4ade80]/20' :
                                                apt.status === 'confirmado' ? 'bg-blue-500/10 text-blue-400 border-blue-500/20' :
                                                    'bg-red-500/10 text-red-500 border-red-500/20'
                                        }`}>
                                        {apt.status.toUpperCase()}
                                    </span>

                                    <div className="flex gap-2 min-w-[80px] justify-end">
                                        {apt.status === 'agendado' && (
                                            <>
                                                <button
                                                    onClick={() => updateAppointmentStatus(apt.id, 'confirmado')}
                                                    className="w-10 h-10 rounded-xl bg-emerald-500/10 text-emerald-500 flex items-center justify-center hover:bg-emerald-500 hover:text-white transition-all shadow-lg shadow-emerald-500/0 hover:shadow-emerald-500/20"
                                                    title="Confirmar"
                                                >
                                                    <Icon name="Check" className="w-5 h-5" />
                                                </button>
                                                <button
                                                    onClick={() => updateAppointmentStatus(apt.id, 'cancelado')}
                                                    className="w-10 h-10 rounded-xl bg-red-500/10 text-red-500 flex items-center justify-center hover:bg-red-500 hover:text-white transition-all shadow-lg shadow-red-500/0 hover:shadow-red-500/20"
                                                    title="Cancelar"
                                                >
                                                    <Icon name="X" className="w-5 h-5" />
                                                </button>
                                            </>
                                        )}
                                        {apt.status !== 'agendado' && (
                                            <button
                                                onClick={() => updateAppointmentStatus(apt.id, 'agendado')}
                                                className="w-10 h-10 rounded-xl bg-[#1a1a1a] text-gray-600 flex items-center justify-center hover:text-white transition-all border border-[#222]"
                                                title="Reverter Status"
                                            >
                                                <Icon name="RotateCcw" className="w-4 h-4" />
                                            </button>
                                        )}
                                    </div>
                                </div>
                            </div>
                        </div>
                    )) : (
                        <div className="h-full flex flex-col items-center justify-center opacity-20 py-20">
                            <Icon name="Inbox" className="w-16 h-16 mb-4" />
                            <p className="text-sm font-bold uppercase tracking-widest text-white">Nenhum agendamento encontrado</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}
